import{_ as r,C as e,o as n,c as a,E as s,a2 as d}from"./chunks/framework.Cm6XCzck.js";const f=JSON.parse('{"title":"TMPA Core Specification — 发布候选版 S0.6","description":"","frontmatter":{"title":"TMPA Core Specification — 发布候选版 S0.6","outline":"deep","citation":{"work":"TMPA Core Specification","identifier":"TMPA-CORE-S0.6","language":"zh","metadata":"/releases/tmpa/v1.0-rc1/metadata/core-specification.zh.cff"}},"headers":[],"relativePath":"zh/publications/tmpa-core-specification-s0.6/part-01.md","filePath":"zh/publications/tmpa-core-specification-s0.6/part-01.md","lastUpdated":1786355271000}'),i={name:"zh/publications/tmpa-core-specification-s0.6/part-01.md"};function l(p,t,c,g,h,P){const o=e("ArticleCover");return n(),a("div",null,[s(o,{image:"/assets/covers/tmpa-spec.svg",kicker:"规范性规范",title:"TMPA Core Specification",summary:"治理对象、生命周期、权限、三值判断与确定性重建的规范要求。",version:"S0.6",status:"发布候选版",languageHref:"/en/publications/tmpa-core-specification-s0.6",languageLabel:"English"}),t[0]||(t[0]=d(`<h1 id="tmpa-core-specification" tabindex="-1">TMPA Core Specification <a class="header-anchor" href="#tmpa-core-specification" aria-label="Permalink to &quot;TMPA Core Specification&quot;">​</a></h1><h2 id="文本化多智能体流程架构——core-对象、reader-语义与一致性" tabindex="-1">文本化多智能体流程架构——Core 对象、Reader 语义与一致性 <a class="header-anchor" href="#文本化多智能体流程架构——core-对象、reader-语义与一致性" aria-label="Permalink to &quot;文本化多智能体流程架构——Core 对象、Reader 语义与一致性&quot;">​</a></h2><blockquote><p><strong>规范版本：</strong> Release Candidate S0.6<br><strong>历史抽取基线：</strong> TMPA Draft V1.0-R24；当前规范直接在本 GitHub 文档中维护<br><strong>状态：</strong> 公开发布候选版<br><strong>抽取日期：</strong> 2026-07-31<br><strong>编辑修订日期：</strong> 2026-08-09<br><strong>权威性：</strong> 本 GitHub 文档是 TMPA Core S0.6 的唯一规范性来源。Architecture Paper 负责理论阐释，Implementation Case Report 负责工程证据；二者均不得重定义本规范。</p></blockquote><hr><h1 id="_1-状态、范围与一致性边界" tabindex="-1">1. 状态、范围与一致性边界 <a class="header-anchor" href="#_1-状态、范围与一致性边界" aria-label="Permalink to &quot;1. 状态、范围与一致性边界&quot;">​</a></h1><p>本文档定义供应商中立的 TMPA Core，固定规范治理对象模型、单写者与生命周期语义、来源聚合、确定性治理重建、三值判断代数、Reader 输出契约、信任假设、规范要求以及 C01–C14 一致性行为。</p><p>TMPA Core 治理流程—责任证据。它不规定模型 Runtime、调度器、存储引擎、消息传输、数据库、文件系统布局、身份提供方、密钥管理系统或企业控制平面。Profile 可以绑定这些机制，但它 <strong>MUST</strong> 保留 Core 语义，并且 <strong>MUST</strong> 明确每一项附加假设或保证。</p><p>本发布候选版区分三类文本：</p><ul><li><strong>规范要求：</strong> 第 9、10 节，使用第 9.1 节规定的规范语言；</li><li><strong>解释规范条款所必需的架构与算法定义：</strong> 第 2–8 节；</li><li><strong>说明性的版本、出版与可追踪信息：</strong> 第 11 节和附录 A。</li></ul><p>除非命名 Profile 明确增加，否则以下能力不属于 TMPA Core：经过认证的企业身份、凭证签发、递归委托、运行时准入控制、受保护或防篡改存储、分布式共识、语义真实性验证、拜占庭韧性、法律认证以及特定司法辖区合规。</p><p>符合规范的实现 <strong>MAY</strong> 使用文件、数据库行、对象存储对象或事件作为来源工件。实现 <strong>MUST NOT</strong> 仅因为存储 Markdown、生成日志或实现工作流状态机就声称符合 TMPA。一致性是行为性质，取决于第 9、10 节规定的可观察对象、生命周期、重建、冲突、恢复与测试结果。</p><p>三份维护文档的出版契约固定如下：<a href="/joinwell52/zh/publications/tmpa-architecture-paper-a0.9">Architecture Paper A0.9</a> 解释理论，本 Core Specification 定义规范行为，<a href="/joinwell52/zh/publications/implementation-case-i0.8">Implementation Case Report I0.8</a> 报告边界明确的工程证据。当前指导关系与历史协同演进必须分开表达：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>当前指导与落实关系</span></span>
<span class="line"><span>TMPA 理论与架构</span></span>
<span class="line"><span>        ↓ 由下列文档形式化为规范行为</span></span>
<span class="line"><span>TMPA Core Specification</span></span>
<span class="line"><span>        ↓ 通过文件型 Profile 投影</span></span>
<span class="line"><span>FCoP 协议</span></span>
<span class="line"><span>        ↓ 被下列系统使用</span></span>
<span class="line"><span>CodeFlowMu 工程系统</span></span>
<span class="line"><span></span></span>
<span class="line"><span>历史协同演进</span></span>
<span class="line"><span>小典 AI 实践 → 早期 TMPA → FCoP 抽取与成熟</span></span>
<span class="line"><span>              → CodeFlowMu 工程落实</span></span>
<span class="line"><span>FCoP + CodeFlowMu 反馈 → 当前 TMPA 形式化</span></span></code></pre></div><p>TMPA 理论指导 CodeFlowMu 工程落实，本 Core 固定接受评估的规范行为，FCoP 提供 CodeFlowMu 使用的协作协议。<code>fcop</code> 与 <code>fcop-mcp</code> Python Package 是 FCoP 协议的参考实现，不是 FCoP 本身。工程反馈可以推动后续 TMPA 修订，但 FCoP 协议、其参考实现和 CodeFlowMu 均不定义、也不穷尽 TMPA Core。</p><hr><h1 id="_2-术语与表示阶段" tabindex="-1">2. 术语与表示阶段 <a class="header-anchor" href="#_2-术语与表示阶段" aria-label="Permalink to &quot;2. 术语与表示阶段&quot;">​</a></h1><p>本规范固定以下词汇，防止把语义对象、物理存储、消息功能与重建视图混为一谈。</p><table tabindex="0"><thead><tr><th>规范英文术语</th><th>固定中文译名</th><th>TMPA 中的固定含义</th><th>不等同于</th></tr></thead><tbody><tr><td><strong>governed work item</strong></td><td><strong>受治理工作项</strong></td><td>其责任与生命周期受到治理的任务、请求、决策或流程主题</td><td>一个文件、一个 Session 或一个 Runtime Job</td></tr><tr><td><strong>primary carrier</strong></td><td><strong>主载体</strong></td><td>锚定一项工作标识符和最低治理上下文的稳定治理对象</td><td>所有参与者共同编辑的可变记录</td></tr><tr><td><strong>governance object</strong></td><td><strong>治理对象</strong></td><td>由一个创建者、以一个责任角色、在一条写者流中编写的规范语义单元</td><td>其存储路径、传输封装或派生视图</td></tr><tr><td><strong>textual message</strong></td><td><strong>文本消息</strong></td><td>治理对象在传递工作、证据、复核或决策语义时承担的通信功能</td><td>单独的对象类别或短暂队列消息</td></tr><tr><td><strong>state carrier</strong></td><td><strong>状态载体</strong></td><td>对象、迁移记录或 Profile 规定位置对声明状态或当前状态证据作出贡献的持久化功能</td><td>共享可变应用状态</td></tr><tr><td><strong>source artifact</strong></td><td><strong>来源工件</strong></td><td>证据的一种物理表示或观测，例如文件、数据库行、对象存储项或收到的事件</td><td>验证后的语义治理对象</td></tr><tr><td><strong>source candidate</strong></td><td><strong>来源候选</strong></td><td>提交给聚合阶段的已发现来源工件，包括格式错误或互相冲突的观测</td><td>已接受的权威对象</td></tr><tr><td><strong>canonical candidate set</strong></td><td><strong>规范候选集合</strong></td><td>聚合返回的、保留来源、完成解析、索引与确定性规范化的集合</td><td>最终治理结论</td></tr><tr><td><strong>writer stream</strong></td><td><strong>写者流</strong></td><td>一个可归属写者发布的、局部有序的治理对象序列</td><td>全局 Event Log 或总时间线</td></tr><tr><td><strong>source aggregator</strong></td><td><strong>来源聚合器</strong></td><td>发现、保留、解析、索引与规范化来源候选，但不决定治理真值的阶段</td><td>治理 Reader</td></tr><tr><td><strong>governance reader</strong></td><td><strong>治理 Reader</strong></td><td>把固定 Profile 应用于规范候选集合的确定性阶段</td><td>存储层、编排器或模型 Runtime</td></tr><tr><td><strong>governance graph and issue set</strong></td><td><strong>治理图与问题集合</strong></td><td>重建得到的偏序流程视图，以及规范化的未解决条件输出</td><td>原始来源证据或人为强加的总顺序</td></tr><tr><td><strong>lifecycle state</strong></td><td><strong>生命周期状态</strong></td><td>Profile 状态机中由有效迁移或状态观测重建的当前阶段</td><td>业务验收、语义真实性或任务价值已经实现</td></tr><tr><td><strong>business acceptance</strong></td><td><strong>业务验收</strong></td><td>有权角色针对交付声明与支持证据发布的独立接受结论</td><td>执行者自述、终态目录位置或 <code>done</code> 标签</td></tr><tr><td><strong>completion claim</strong></td><td><strong>完成声明</strong></td><td>对某一工作项、交付物或子工作集合已经满足要求的可审查断言</td><td>自证成立的完成事实</td></tr><tr><td><strong>work derivation</strong></td><td><strong>工作派生关系</strong></td><td>父工作与子工作之间保留范围、责任和闭环要求的显式关系</td><td>运行时临时分叉或无来源的任务列表</td></tr><tr><td><strong>governance decision</strong></td><td><strong>治理裁决</strong></td><td>复核、批准、拒绝、要求修改、回避或升级人工的独立对象</td><td>生命周期中的 <code>review</code> 阶段本身</td></tr><tr><td><strong>inspection finding</strong></td><td><strong>巡检发现</strong></td><td>Reader、审计器或治理告警组件发现的可复现偏差或风险信号</td><td>已自动执行的修复或业务裁决</td></tr></tbody></table><p>三份文档统一使用三个语义判断：<code>valid</code>（<strong>有效</strong>）表示适用证据与规则建立接受结论；<code>invalid</code>（<strong>无效</strong>）表示规则建立拒绝或违规；<code>undetermined</code>（<strong>未确定</strong>）表示证据不完整、相互冲突或等待授权解决。authoritative、quarantined、partial、disputed、pending_human 等视图标签只解释呈现原因，不构成额外语义值。</p><p>同一个规范治理对象可以由不同物理 Profile 实现。在 FCoP 中，来源工件通常是文件及其路径与事件证据；其他 Profile 可以使用数据库行、对象或事件。两个来源工件若声明相同对象 ID、却包含不同规范内容，则不是无害副本，而是必须保留并按 Profile 评估的冲突候选。</p><p>本文中的 **object（对象）**指语义单元，**artifact（工件）**指物理或已发布的工程表示，**view（视图）**指 Reader 派生的结果。实现及文档 <strong>MUST</strong> 保持这三个层次的区别。</p><hr><h1 id="_3-core-架构模型" tabindex="-1">3. Core 架构模型 <a class="header-anchor" href="#_3-core-架构模型" aria-label="Permalink to &quot;3. Core 架构模型&quot;">​</a></h1><p>TMPA 定义治理语义，而不是某个 Runtime 组件。它规定必须表示哪些治理事实、责任与生命周期如何表达，以及独立证据如何重建为可判断的治理视图。除非 TMPA Profile 明确绑定，否则存储、传输、调度与模型行为仍属于实现问题。</p><h2 id="_3-1-治理对象" tabindex="-1">3.1 治理对象 <a class="header-anchor" href="#_3-1-治理对象" aria-label="Permalink to &quot;3.1 治理对象&quot;">​</a></h2><p><strong>治理对象</strong>是 TMPA 中最小的、能够独立归属责任的语义单元。它可以表示任务、报告、复核、批准、问题、生命周期迁移、角色分配、恢复动作或协议 Profile 发布的其他文档类型。对象不同于物理来源工件。</p><p><strong>文本消息</strong>与<strong>状态载体</strong>描述对象承担的功能，而不是额外对象类别。对象在传递受治理工作或证据时承担文本消息功能；其内容、迁移证据或 Profile 规定位置参与生命周期重建时承担状态载体功能。</p><p>每个治理对象包含或标识：</p><ul><li>稳定对象 ID；</li><li>文档类型；</li><li>一个创建者身份；</li><li>一个责任角色；</li><li>写者流 ID 与序号；</li><li>创建时间；</li><li>生命周期 Profile 与声明状态；</li><li>指向相关对象的类型化引用；</li><li>可选的父工作与 Thread 标识；</li><li>可选的完成、失败、恢复或验收声明及其证据引用；</li><li>Profile 要求时的风险等级与人工审批要求；</li><li>规范文本内容；</li><li>完整性证据。</li></ul><p>已发布治理对象不可变。更正 <strong>MUST NOT</strong> 擦除或重写原对象，而 <strong>MUST</strong> 创建新的对象，对原对象进行取代、拒绝、限定或解决。多个字节相同的来源观测可以指向同一对象；相同 ID 配合不同规范内容构成冲突，不构成更新。</p><p>对象声明的生命周期状态是发布时按照其 Profile 关联的状态。受治理工作的当前权威状态 <strong>MUST</strong> 从有效对象集合、已接受迁移和 Profile 规则中重建；实现 <strong>MUST NOT</strong> 通过修改旧对象或选择时间戳最新的对象得到权威状态。</p><p>生命周期状态与业务验收是两个正交维度。对象位于终态、归档位置或声明 <code>done</code> 只能构成状态证据；除非适用 Profile 明确规定验收权限、必需交付证据和职责分离，并且 Reader 找到有效的接受对象，否则它 <strong>MUST NOT</strong> 被重建为业务完成。</p><h2 id="_3-2-文档类型注册表" tabindex="-1">3.2 文档类型注册表 <a class="header-anchor" href="#_3-2-文档类型注册表" aria-label="Permalink to &quot;3.2 文档类型注册表&quot;">​</a></h2><p>TMPA Core 不规定统一的业务文档分类。每个实现 Profile <strong>MUST</strong> 发布有限的文档类型注册表。每项注册内容包括：</p><ul><li>类型名称与版本；</li><li>类型所表达的治理责任；</li><li>允许的创建者角色；</li><li>必填字段；</li><li>允许的引用关系；</li><li>适用的生命周期 Profile；</li><li>验证规则。</li></ul><p>文档类型在权威上 <strong>MUST NOT</strong> 模糊重叠。例如，执行报告不得自动充当自己的独立复核或批准。部署允许职责分离例外时，例外及其批准权限 <strong>MUST</strong> 由显式对象表示。</p><h2 id="_3-3-角色与权限模型" tabindex="-1">3.3 角色与权限模型 <a class="header-anchor" href="#_3-3-角色与权限模型" aria-label="Permalink to &quot;3.3 角色与权限模型&quot;">​</a></h2><p>TMPA 角色是具有确定范围的治理权限，不是 Prompt 标签或自然语言人格。</p><p>每个角色定义包括：稳定角色 ID、允许创建的对象类型、允许执行的生命周期动作、职责分离约束、角色授予方、分配有效期与撤销状态。</p><p>Profile <strong>MAY</strong> 把角色组织为执行、治理与管理等能力层，但必须声明层级含义、允许方向、禁止方向以及由何种身份或 Runtime 控制实际执行。声明性能力边界与已强制执行的能力边界 <strong>MUST</strong> 分开报告。</p><p>对象的 <code>role</code> 字段声明创建者以何种权限行动，但它不会自行创造权限。Reader <strong>MUST</strong> 根据有效角色分配与适用策略 Profile 验证该声明。</p><p>只有实现 Profile 明确允许时，一个参与者 <strong>MAY</strong> 同时占据多个角色。声称独立复核的部署 <strong>MUST</strong> 禁止同一身份对同一受治理结果同时担任执行者和复核者，除非存在经过记录并获得授权的例外对象。</p><p>在企业身份 Profile 中，逻辑角色应分别绑定到可验证的 Agent 或工作负载身份、继续承担责任的人类或组织主体、此次动作使用的凭证、委托来源与范围，以及有效或撤销状态。TMPA Core 记录和验证治理声明，但不签发凭证，也不强制递归权限衰减。</p><h2 id="_3-4-生命周期模型" tabindex="-1">3.4 生命周期模型 <a class="header-anchor" href="#_3-4-生命周期模型" aria-label="Permalink to &quot;3.4 生命周期模型&quot;">​</a></h2><p>生命周期 Profile 由以下元素构成：</p><ul><li>有限状态集合 <code>S</code>；</li><li>初始状态 <code>s0</code>；</li><li>终止状态集合 <code>F</code>；</li><li>动作集合 <code>A</code>；</li><li>迁移关系 <code>T ⊆ S × A × S</code>；</li><li>授权函数 <code>Auth(role, action, object)</code>；</li><li>验证函数 <code>Valid(object, transition)</code>。</li></ul><p>只有同时满足以下条件，迁移才被接受：来源状态匹配当前权威状态；迁移存在于 <code>T</code>；发起角色已获授权；必需引用与前置条件已满足；迁移证据通过 Schema 与完整性验证。</p><p>非法或未经授权的迁移 <strong>MUST NOT</strong> 改变权威生命周期状态。该尝试 <strong>MUST</strong> 通过拒绝、ISSUE、告警或 Profile 规定的等价记录保持可观察，不得静默丢弃或修复。</p><p>生命周期 Profile 还 <strong>MUST</strong> 声明：(1) 哪些状态需要独立业务验收；(2) 哪些关系构成报告、复核、接受与归档授权；(3) 父子工作如何汇总；(4) 哪些风险等级需要人工批准；(5) 失败类型、恢复动作及其持久证据。生命周期工具或物理位置可以实现这些规则，但不能取代这些语义定义。</p><h2 id="_3-5-文本消息、单写者流与异步并行" tabindex="-1">3.5 文本消息、单写者流与异步并行 <a class="header-anchor" href="#_3-5-文本消息、单写者流与异步并行" aria-label="Permalink to &quot;3.5 文本消息、单写者流与异步并行&quot;">​</a></h2><p>TMPA 写入面由稳定工作载体、单写者对象、局部串行性和异步组合构成。</p><p>对于每个受治理工作项 <code>t</code>，面向任务的 Profile <strong>MUST</strong> 定义一个稳定主载体 <code>c_t</code>。主载体建立工作 ID 和最低治理上下文。接受、执行报告、复核、决策、更正与恢复记录 <strong>MUST</strong> 是引用 <code>c_t</code> 的独立对象，不得成为任务的额外可变副本。“一任务一载体”指一个稳定主引用点，而不是一份多人共同编辑的文档。</p><p>令 <code>A</code> 为责任写者集合。每个已发布对象恰好有一个写者；每个写者 <code>a ∈ A</code> 发布一条可独立归属的串行流：</p><p><code>S_a = ⟨o_{a,1}, o_{a,2}, ..., o_{a,n}⟩</code></p><p><code>S_a</code> 内的序号是权威局部顺序。每个对象 <strong>MUST</strong> 具有正整数序号，<code>(stream_id, sequence)</code> 标识它在写者责任历史中的位置。创建时间仅供说明，<strong>MUST NOT</strong> 取代流内顺序。</p><p>在观测时刻 <code>τ</code>，可见候选可以是不同流的不同前缀：</p><p><code>O_τ = ⋃_{a ∈ A} prefix(S_a, k_a(τ))</code></p><p>各 <code>k_a(τ)</code> 无需同步推进。一个参与者可以先发布任务，另一个参与者稍后提交报告，多条流可以并行进展。这就是多条串行流形成异步并行的方式。TMPA 不要求共享时钟、同时在线或使用一个全局事件日志。</p><p>流内前驱关系产生局部顺序；显式引用与 Profile 定义的生命周期依赖产生跨流因果边。若两个对象既不存在流内关系，也不存在 Profile 定义的跨流依赖，它们 <strong>MUST</strong> 保持并发且不可比较。</p><p>单写者对象与独立责任流消除了主要的语义共享写冲突，但不消除所有存储争用、文件系统竞态或基础设施故障。Profile <strong>MUST</strong> 定义原子发布、重复处理与恢复行为。</p><blockquote><p><strong>一项任务有一个主载体；每个已发布对象只有一个写者；每个写者保持串行；多条流异步推进并形成并行协作。</strong></p></blockquote>`,61))])}const T=r(i,[["render",l]]);export{f as __pageData,T as default};
